/** Genuine default-format fresh imports must retain current persisted predicate-domain semantics. */
class LmdbPreparedDomainCompositionTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI INTEGERS = VF.createIRI("urn:prepared-domain:integer");
	private static final IRI NONCANONICAL = VF.createIRI("urn:prepared-domain:noncanonical");
	private static final IRI LANGUAGE = VF.createIRI("urn:prepared-domain:language");
	private static final IRI RESOURCE = VF.createIRI("urn:prepared-domain:resource");

	enum Route {
		SCALAR,
		PREPARED,
		GLOBAL
	}

	@ParameterizedTest
	@EnumSource(value = Route.class, names = { "SCALAR", "PREPARED" })
	void freshPreparedDomainsMatchScalarAndSurviveReopen(Route route, @TempDir Path directory) throws Exception {
		verifyRoute(route, directory, false);
	}

	@ParameterizedTest
	@EnumSource(value = Route.class, names = { "SCALAR", "PREPARED" })
	void preparedMixedDomainsStayQualifiedAcrossReopen(Route route, @TempDir Path directory) throws Exception {
		verifyRoute(route, directory, true);
	}

	static void verifyRoute(Route route, Path directory, boolean mixed) throws Exception {
		boolean global = route == Route.GLOBAL;
		LmdbStoreConfig config = new LmdbStoreConfig(global ? "spoc,ospc,posc,psoc" : "spoc,posc,ospc")
				.setBulkOperationSize(route == Route.SCALAR ? 0 : 1024)
				.setInlineLiterals(false)
				.setPredicateGuaranteeIndexAutoRebuild(false);
		int secondaryIndexes = global ? 3 : 2;
		int capacity = LmdbSailStore.calculatePreparedImportStatementLimit(Runtime.getRuntime().maxMemory(),
				secondaryIndexes);
		// GLOBAL is a separately selected test, never included in the small initial red selection.
		int count = global ? Math.max(1024, Math.addExact(capacity, 1)) : 1024;
		List<Statement> rows = rows(count, mixed);
		AtomicReference<ObservedTripleStore> observed = new AtomicReference<>();
		LmdbStore store = new LmdbStore(directory.toFile(), config) {
			@Override
			LmdbSailStore createBackingStore(File dataDir, StoreProperties properties, LmdbStoreConfig selected,
					boolean sketchEnabled) throws IOException {
				assertFalse(sketchEnabled, "fresh prepared route requires the actual sketch-free store profile");
				return new LmdbSailStore(dataDir, properties, selected, false, null,
						(dir, props, cfg, values) -> {
							ObservedTripleStore triples = new ObservedTripleStore(dir, props, cfg, values);
							observed.set(triples);
							return triples;
						});
			}
		};
		store.init();
		try {
			LmdbSailStore backing = store.getBackingStore();
			ObservedTripleStore triples = observed.get();
			assertTrue(triples.isEmpty(), "fresh physical store is a route precondition");
			assertEquals(global, triples.supportsGlobalPreparedOrder());
			try (SailSink sink = backing.getExplicitSailSource().sink(IsolationLevels.READ_COMMITTED)) {
				// Actual direct backing sink avoids connection-owned NONE checkpoint mode; no private state is forced.
				assertEquals(count, sink.approveAll(rows));
				if (route != Route.SCALAR) {
					assertTrue(backing.hasActiveFreshValueSession(), "actual fresh dictionary session must be active");
				}
				sink.flush();
			}
			if (route == Route.SCALAR) {
				assertEquals(0, triples.preparedCalls);
				assertEquals(0, triples.globalCalls);
			} else if (global) {
				assertTrue(count > capacity, "production capacity formula must select actual global operation");
				assertTrue(triples.globalCalls > 0, "observed real native global API must execute");
			} else {
				assertTrue(triples.preparedCalls > 0, "observed real prepared native API must execute");
				assertEquals(0, triples.globalCalls);
			}
			assertRows(backing, Set.copyOf(rows));
			assertDomains(backing, count, true, mixed);
			// Duplicate physical input must not widen a guarantee or introduce another statement.
			try (SailSink sink = backing.getExplicitSailSource().sink(IsolationLevels.READ_COMMITTED)) {
				Statement first = rows.getFirst();
				sink.approve(first.getSubject(), first.getPredicate(), first.getObject(), first.getContext());
				sink.flush();
			}
			assertRows(backing, Set.copyOf(rows));
			assertDomains(backing, count, true, mixed);
		} finally {
			store.shutDown();
		}

		// Auto-rebuild is explicitly off: reopen must preserve what the write itself committed.
		store.init();
		try {
			LmdbSailStore backing = store.getBackingStore();
			assertRows(backing, Set.copyOf(rows));
			assertDomains(backing, count, true, mixed);
			try (SailSink aborted = backing.getExplicitSailSource().sink(IsolationLevels.READ_COMMITTED)) {
				aborted.approve(VF.createIRI("urn:prepared-domain:aborted"), INTEGERS,
						VF.createLiteral("000999999", XSD.INT), null);
				// Closing an unflushed real backing sink aborts its writer.
			}
			assertRows(backing, Set.copyOf(rows));
			assertDomains(backing, count, true, mixed);
			Statement broadened = VF.createStatement(VF.createIRI("urn:prepared-domain:broadened"), INTEGERS,
					VF.createLiteral("000999999", XSD.INT));
			try (SailSink sink = backing.getExplicitSailSource().sink(IsolationLevels.READ_COMMITTED)) {
				sink.approve(broadened.getSubject(), broadened.getPredicate(), broadened.getObject(), null);
				sink.flush();
			}
			rows.add(broadened);
			assertRows(backing, Set.copyOf(rows));
			assertDomains(backing, count, false, mixed);
		} finally {
			store.shutDown();
		}
		store.init();
		try {
			assertRows(store.getBackingStore(), Set.copyOf(rows));
			assertDomains(store.getBackingStore(), count, false, mixed);
		} finally {
			store.shutDown();
		}
	}

	private static List<Statement> rows(int count, boolean mixed) {
		List<Statement> result = new ArrayList<>(count);
		for (int i = 0; i < count; i++) {
			IRI subject = VF.createIRI("urn:prepared-domain:s:" + i);
			IRI context = (i & 1) == 0 ? null : VF.createIRI("urn:prepared-domain:graph");
			switch (mixed ? i % 4 : 0) {
			case 0 -> result.add(VF.createStatement(subject, INTEGERS, VF.createLiteral(i), context));
			case 1 -> result.add(VF.createStatement(subject, NONCANONICAL, VF.createLiteral("007", XSD.INT), context));
			case 2 -> result.add(VF.createStatement(subject, LANGUAGE, VF.createLiteral("Word", "EN"), context));
			case 3 -> result.add(VF.createStatement(subject, RESOURCE, VF.createIRI("urn:prepared-domain:o"), context));
			}
		}
		return result;
	}

	private static void assertDomains(LmdbSailStore backing, int count, boolean canonical, boolean mixed)
			throws Exception {
		RdfTermDomain integers = domain(backing, INTEGERS);
		assertTrue(integers.has(RdfTermDomain.Fact.NUMBER));
		assertEquals(canonical, integers.has(RdfTermDomain.Fact.CANONICAL_INTEGER));
		if (canonical) {
			assertEquals(new RdfTermDomain.IntegerRange(0L, mixed ? ((count - 1L) / 4L) * 4L : count - 1L),
					integers.integerRange().orElseThrow());
		} else {
			assertTrue(integers.integerRange().isEmpty());
		}
		if (!mixed) {
			return;
		}
		RdfTermDomain noncanonical = domain(backing, NONCANONICAL);
		assertTrue(noncanonical.has(RdfTermDomain.Fact.NUMBER));
		assertFalse(noncanonical.has(RdfTermDomain.Fact.CANONICAL_INTEGER));
		assertTrue(domain(backing, LANGUAGE).has(RdfTermDomain.Fact.LITERAL_WITH_LANGUAGE));
		assertTrue(domain(backing, RESOURCE).has(RdfTermDomain.Fact.IRI));
	}

	private static RdfTermDomain domain(LmdbSailStore backing, IRI predicate) throws Exception {
		RdfTermDomain cached = backing.getCachedRdfTermDomain(predicate).orElseThrow();
		assertEquals(cached, backing.getPersistedRdfTermDomain(predicate).orElseThrow(),
				"heap and durable domains agree");
		LmdbPredicateObjectDomainSource planner = (LmdbPredicateObjectDomainSource) backing.getEvaluationStatistics();
		assertEquals(cached, planner.getKnownRdfTermDomain(predicate).orElseThrow(),
				"real planner sees the committed domain");
		return cached;
	}

	private static void assertRows(LmdbSailStore backing, Set<Statement> expected) {
		Set<Statement> actual = new LinkedHashSet<>();
		try (SailDataset dataset = backing.getExplicitSailSource().dataset(IsolationLevels.READ_COMMITTED);
				var rows = dataset.getStatements(null, null, null)) {
			while (rows.hasNext()) {
				actual.add(rows.next());
			}
		}
		assertEquals(expected, actual, "exact terms and named/default graph rows survive each transition");
	}

	private static final class ObservedTripleStore extends TripleStore {
		int preparedCalls;
		int globalCalls;

		ObservedTripleStore(File directory, StoreProperties properties, LmdbStoreConfig config, ValueStore values)
				throws IOException {
			super(directory, properties, config, values);
		}

		@Override
		void storePreparedTriples(long[] subjects, long[] predicates, long[] objects, long[] contexts, int count,
				boolean explicit, boolean mayHaveInferred, IntConsumer added, EncodedIndexKeys main,
				PreparedSecondaryIndexesSupplier secondary) throws IOException {
			preparedCalls++;
			super.storePreparedTriples(subjects, predicates, objects, contexts, count, explicit, mayHaveInferred,
					added, main, secondary);
		}

		@Override
		int storeGloballyOrderedFreshTriples(int[] quads, long[] values, int count,
				GlobalPreparedIndexOrdersTask orders,
				ExecutorService executor, IntConsumer added) throws IOException {
			globalCalls++;
			return super.storeGloballyOrderedFreshTriples(quads, values, count, orders, executor, added);
		}
	}
}
